ALTER TABLE "procedure_version" ADD COLUMN "compliance_compiler_version" text DEFAULT '1' NOT NULL;--> statement-breakpoint
ALTER TABLE "procedure_version" ADD COLUMN "compliance_conditions" jsonb;--> statement-breakpoint
